// Generated by npm run assets:portrait after exporting the working copies.
export const PORTRAIT_FRAMES={"standard":"/assets/athlete-v8-standard.glb?revision=7ca64aa9cb7e","tall":"/assets/athlete-v8-tall.glb?revision=8b9ee7c39534","broad":"/assets/athlete-v8-broad.glb?revision=63c919ca70bf"} as const;
export const PORTRAIT_ASSET_URL=PORTRAIT_FRAMES.standard;
/** Stable adult frame, never chosen from muscle or fat. Existing saves need no migration. */
export function portraitFrame(height:number):keyof typeof PORTRAIT_FRAMES{return height>=182?'tall':height<=170?'broad':'standard';}
export function portraitAsset(height:number){return PORTRAIT_FRAMES[portraitFrame(height)];}
export const GYM_ASSET_URL='/assets/gym-v4-room.glb?revision=23ef69bad587';
